// Base methods call this.end(...) with differently typed arguments; Pool overrides end with the
// same arity, Leaf with a different signature.
class Base {
  constructor(id) { this.id = id; this._closing = false; }
  end(cb) { return "base-end:" + this.id + ":" + typeof cb; }
  close() { if (!this._closing) { return this.end(); } return "closing"; }
  finish(x) { return this.end(x); }
  twice(n) { return this.end(n) + "|" + this.end("s" + n); }
}
class Pool extends Base {
  end(cb) { return "pool-end:" + this.id + ":" + typeof cb + ":" + (cb === undefined ? "none" : cb); }
}
class Leaf extends Pool {
  end(cb, extra) { return "leaf-end:" + this.id + ":" + cb + ":" + extra; }
}
module.exports = { Base, Pool, Leaf };
